  border-radius: 20px;
}

.xt-section {
  background: rgba(0,0,0,0.5);
  border-radius: 12px;
  padding: 14px;
  margin: 0 14px 10px;
  border: 1px solid var(--xt-border);
  z-index: 2;
}
.xt-section-title {
  font-size: 12px;
  color: #ff5599;
  letter-spacing: 1px;
  margin:0;
}
